#include <stdio.h>
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    long long a[100005];
    for (int i = 0; i < n; i++) scanf("%lld", &a[i]);
    long long cand = a[0]; int count = 1;
    for (int i = 1; i < n; i++) {
        if (count == 0) { cand = a[i]; count = 1; }
        else if (a[i] == cand) count++;
        else count--;
    }
    int freq = 0;
    for (int i = 0; i < n; i++) if (a[i] == cand) freq++;
    if (freq > n / 2) printf("%lld\n", cand);
    else printf("-1\n");
    return 0;
}

